import{_ as e,o as i,c as a,ao as l}from"./chunks/framework.DJpdxKta.js";const r="/BVDOutbreakSize/previews/PR1118/assets/province_map.CnI6us92.png",d="/BVDOutbreakSize/previews/PR1118/assets/cases_rt_provinces.D3dRgUdf.png",s="/BVDOutbreakSize/previews/PR1118/assets/cases_rt_zones.DbEBF-b9.png",n="/BVDOutbreakSize/previews/PR1118/assets/rt.DPuPmS8P.png",g="/BVDOutbreakSize/previews/PR1118/assets/province-57.Dhtw7C6X.png",h="/BVDOutbreakSize/previews/PR1118/assets/infections.o9kUsxBo.png",f=JSON.parse('{"title":"Summary dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"estimates/summary.md","filePath":"estimates/summary.md","lastUpdated":null}'),o={name:"estimates/summary.md"};function y(x,t,c,p,m,u){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="Summary-dashboard" tabindex="-1">Summary dashboard <a class="header-anchor" href="#Summary-dashboard" aria-label="Permalink to &quot;Summary dashboard {#Summary-dashboard}&quot;">​</a></h1><p><strong>Last updated:</strong> 9 October 2026.</p><p><strong>Data as of:</strong> 6 October 2026.</p><p>See <a href="./../methods">Methods</a> for the model and the definition of each quantity.</p><h2 id="Headline-estimates" tabindex="-1">Headline estimates <a class="header-anchor" href="#Headline-estimates" aria-label="Permalink to &quot;Headline estimates {#Headline-estimates}&quot;">​</a></h2><ul><li><p><strong>Cumulative infections:</strong> the outbreak is estimated to have caused 30% 17258–20705, 60% 15763–22985, 90% 13538–28051 infections to date, reported and unreported.</p></li><li><p>Against the 8728 laboratory-confirmed cases by the cut-off that is roughly 1.6–3.2× as many infections, so confirmed cases are estimated to capture only a small share of the outbreak.</p></li><li><p><strong>Outbreak start and age:</strong> the outbreak is estimated to have begun on a start date of 30% 2026-03-13–2026-03-19, 60% 2026-03-09–2026-03-22, 90% 2026-02-27–2026-03-26, an elapsed age to the cut-off of 30% 201–207, 60% 198–211, 90% 194–221 days.</p></li><li><p><strong>Growth rate and doubling time:</strong> the initial growth rate is estimated to have been 30% 0.056–0.069, 60% 0.049–0.077, 90% 0.04–0.092 per day, an initial doubling time of 30% 12.4–10.0, 60% 14.1–9.0, 90% 17.5–7.5 days. The latest growth rate is estimated to be 30% -0.003–0.009, 60% -0.01–0.016, 90% -0.022–0.032 per day, a latest doubling time of 30% -211.4–81.5, 60% -67.0–43.5, 90% -30.9–21.8 days.</p></li><li><p><strong>Reproduction number:</strong> the initial reproduction number is estimated to have been 30% 1.88–2.16, 60% 1.76–2.36, 90% 1.58–2.73 and the latest to be 30% 0.96–1.11, 60% 0.87–1.22, 90% 0.73–1.47.</p></li><li><p><strong>Case-fatality ratio:</strong> the case-fatality ratio is estimated to be 30% 0.47–0.52, 60% 0.44–0.55, 90% 0.39–0.6.</p></li><li><p><strong>Shift from priors:</strong> how far the data has moved each estimate from its prior, in prior interquartile ranges, where a value of one means the posterior median sits one prior interquartile range from the prior median, zero means unchanged, and the sign gives the direction. The fit moves the cumulative infection count by -0.05, the outbreak age by -1.18 and the doubling time by 0.25; the largest move is in the outbreak age.</p></li></ul><h3 id="Outbreak-size-and-timing" tabindex="-1">Outbreak size and timing <a class="header-anchor" href="#Outbreak-size-and-timing" aria-label="Permalink to &quot;Outbreak size and timing {#Outbreak-size-and-timing}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Quantity</th><th style="text-align:right;">Lower 90%</th><th style="text-align:right;">Lower 60%</th><th style="text-align:right;">Lower 30%</th><th style="text-align:right;">Upper 30%</th><th style="text-align:right;">Upper 60%</th><th style="text-align:right;">Upper 90%</th></tr></thead><tbody><tr><td style="text-align:right;">Cumulative infections</td><td style="text-align:right;">13538</td><td style="text-align:right;">15763</td><td style="text-align:right;">17258</td><td style="text-align:right;">20705</td><td style="text-align:right;">22985</td><td style="text-align:right;">28051</td></tr><tr><td style="text-align:right;">Outbreak age (days)</td><td style="text-align:right;">194</td><td style="text-align:right;">198</td><td style="text-align:right;">201</td><td style="text-align:right;">207</td><td style="text-align:right;">211</td><td style="text-align:right;">221</td></tr></tbody></table><h3 id="Growth-and-severity" tabindex="-1">Growth and severity <a class="header-anchor" href="#Growth-and-severity" aria-label="Permalink to &quot;Growth and severity {#Growth-and-severity}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Quantity</th><th style="text-align:right;">Lower 90%</th><th style="text-align:right;">Lower 60%</th><th style="text-align:right;">Lower 30%</th><th style="text-align:right;">Upper 30%</th><th style="text-align:right;">Upper 60%</th><th style="text-align:right;">Upper 90%</th></tr></thead><tbody><tr><td style="text-align:right;">Initial reproduction number</td><td style="text-align:right;">1.58</td><td style="text-align:right;">1.76</td><td style="text-align:right;">1.88</td><td style="text-align:right;">2.16</td><td style="text-align:right;">2.36</td><td style="text-align:right;">2.73</td></tr><tr><td style="text-align:right;">Latest reproduction number</td><td style="text-align:right;">0.73</td><td style="text-align:right;">0.87</td><td style="text-align:right;">0.96</td><td style="text-align:right;">1.11</td><td style="text-align:right;">1.22</td><td style="text-align:right;">1.47</td></tr><tr><td style="text-align:right;">Latest growth rate (per day)</td><td style="text-align:right;">-0.02</td><td style="text-align:right;">-0.01</td><td style="text-align:right;">0</td><td style="text-align:right;">0.01</td><td style="text-align:right;">0.02</td><td style="text-align:right;">0.03</td></tr><tr><td style="text-align:right;">Latest doubling time (days)</td><td style="text-align:right;">-30.89</td><td style="text-align:right;">-66.99</td><td style="text-align:right;">-211.44</td><td style="text-align:right;">81.53</td><td style="text-align:right;">43.51</td><td style="text-align:right;">21.77</td></tr><tr><td style="text-align:right;">Case-fatality ratio</td><td style="text-align:right;">0.39</td><td style="text-align:right;">0.44</td><td style="text-align:right;">0.47</td><td style="text-align:right;">0.52</td><td style="text-align:right;">0.55</td><td style="text-align:right;">0.6</td></tr></tbody></table><p>Equal-tailed 30%, 60% and 90% credible intervals from the joint posterior.</p><h3 id="By-province" tabindex="-1">By province <a class="header-anchor" href="#By-province" aria-label="Permalink to &quot;By province {#By-province}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Province</th><th style="text-align:right;">Infections to date</th><th style="text-align:right;">R at the cut-off</th><th style="text-align:right;">Confirmed cases, latest week</th></tr></thead><tbody><tr><td style="text-align:right;">Ituri</td><td style="text-align:right;">9264–19421</td><td style="text-align:right;">0.65–1.32</td><td style="text-align:right;">263</td></tr><tr><td style="text-align:right;">Nord-Kivu</td><td style="text-align:right;">3217–7444</td><td style="text-align:right;">0.71–1.81</td><td style="text-align:right;">215</td></tr><tr><td style="text-align:right;">Haut-Uele</td><td style="text-align:right;">530–1263</td><td style="text-align:right;">0.48–1.37</td><td style="text-align:right;">20</td></tr><tr><td style="text-align:right;">Other provinces</td><td style="text-align:right;">100–281</td><td style="text-align:right;">0.61–1.68</td><td style="text-align:right;">6</td></tr></tbody></table><p>Equal-tailed 90% credible intervals. Confirmed cases are the reported count over the latest week of situation reports.</p><p><img src="'+r+'" alt=""></p><p>Modelled infections to date by province, shaded by the posterior median on a log scale.</p><p><img src="'+d+'" alt=""></p><h3 id="By-health-zone" tabindex="-1">By health zone <a class="header-anchor" href="#By-health-zone" aria-label="Permalink to &quot;By health zone {#By-health-zone}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Zone</th><th style="text-align:right;">Province</th><th style="text-align:right;">Cases, past two weeks</th><th style="text-align:right;">Cases to date</th><th style="text-align:right;">Share of province infections (%)</th><th style="text-align:right;">R at the cut-off</th><th style="text-align:right;">P(R &gt; 1)</th><th style="text-align:right;">Confirmed cases, next week</th><th style="text-align:right;">R modelled separately</th></tr></thead><tbody><tr><td style="text-align:right;">Mandima</td><td style="text-align:right;">Ituri</td><td style="text-align:right;">132</td><td style="text-align:right;">198</td><td style="text-align:right;">8–68</td><td style="text-align:right;">0.36–1.9</td><td style="text-align:right;">52%</td><td style="text-align:right;">29–162</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;">Beni</td><td style="text-align:right;">Nord-Kivu</td><td style="text-align:right;">117</td><td style="text-align:right;">409</td><td style="text-align:right;">18–51</td><td style="text-align:right;">0.54–1.53</td><td style="text-align:right;">45%</td><td style="text-align:right;">33–147</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;">Bunia</td><td style="text-align:right;">Ituri</td><td style="text-align:right;">112</td><td style="text-align:right;">1790</td><td style="text-align:right;">5–38</td><td style="text-align:right;">0.28–1.42</td><td style="text-align:right;">27%</td><td style="text-align:right;">24–140</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;">Katwa</td><td style="text-align:right;">Nord-Kivu</td><td style="text-align:right;">60</td><td style="text-align:right;">608</td><td style="text-align:right;">7–24</td><td style="text-align:right;">0.55–1.56</td><td style="text-align:right;">43%</td><td style="text-align:right;">11–81</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;">Rwampara</td><td style="text-align:right;">Ituri</td><td style="text-align:right;">57</td><td style="text-align:right;">1118</td><td style="text-align:right;">3–25</td><td style="text-align:right;">0.31–1.68</td><td style="text-align:right;">34%</td><td style="text-align:right;">11–94</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;">Nia-Nia</td><td style="text-align:right;">Ituri</td><td style="text-align:right;">45</td><td style="text-align:right;">314</td><td style="text-align:right;">1–13</td><td style="text-align:right;">0.16–1.45</td><td style="text-align:right;">16%</td><td style="text-align:right;">1–44</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;">Butembo</td><td style="text-align:right;">Nord-Kivu</td><td style="text-align:right;">33</td><td style="text-align:right;">286</td><td style="text-align:right;">5–17</td><td style="text-align:right;">0.58–1.62</td><td style="text-align:right;">49%</td><td style="text-align:right;">5–59</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;">Nizi</td><td style="text-align:right;">Ituri</td><td style="text-align:right;">30</td><td style="text-align:right;">792</td><td style="text-align:right;">1–12</td><td style="text-align:right;">0.28–1.52</td><td style="text-align:right;">27%</td><td style="text-align:right;">2–51</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;">Mabalako</td><td style="text-align:right;">Nord-Kivu</td><td style="text-align:right;">27</td><td style="text-align:right;">51</td><td style="text-align:right;">4–23</td><td style="text-align:right;">0.72–2.22</td><td style="text-align:right;">75%</td><td style="text-align:right;">3–54</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;">Mangala</td><td style="text-align:right;">Ituri</td><td style="text-align:right;">25</td><td style="text-align:right;">366</td><td style="text-align:right;">1–8</td><td style="text-align:right;">0.21–1.51</td><td style="text-align:right;">21%</td><td style="text-align:right;">0–36</td><td style="text-align:right;">yes</td></tr></tbody></table><p>The 10 zones with the most confirmed cases over the past two weeks, of the 44 of 64 with a case in that time.</p><p>The zones with the most confirmed cases over the past two weeks, with equal-tailed 90% credible intervals.</p><p><img src="'+s+'" alt=""></p><h3 id="Health-zone-forecast" tabindex="-1">Health-zone forecast <a class="header-anchor" href="#Health-zone-forecast" aria-label="Permalink to &quot;Health-zone forecast {#Health-zone-forecast}&quot;">​</a></h3><p>Projected counts are for the week to 2026-10-13.</p><ul><li><p><strong>Most new confirmed cases:</strong> Mandima about 78 (90% credible interval 29 to 162); Beni about 77 (90% credible interval 33 to 147); Bunia about 64 (90% credible interval 24 to 140).</p></li><li><p><strong>Chance of a case:</strong> 30 of 64 zones have at least an even chance of reporting a confirmed case, and 12 of reporting at least ten.</p></li><li><p><strong>Quiet zones:</strong> 20 zones have had no case allocated over the past two weeks. Kabondo is the most likely of them to report one, at 48%.</p></li></ul><h3 id="Fit-diagnostics" tabindex="-1">Fit diagnostics <a class="header-anchor" href="#Fit-diagnostics" aria-label="Permalink to &quot;Fit diagnostics {#Fit-diagnostics}&quot;">​</a></h3><p>The joint fit fails the convergence checks.</p><details><summary>Expand: how the fits behind these numbers sampled</summary><p>Its worst R-hat is 1.07 and its lowest bulk effective sample size is 53, with 2 divergent transitions in 2000 draws. A fit passes without warnings when its worst R-hat is at most 1.05, its effective sample sizes are at least 100 and at most 1% of its draws diverge.</p><p>Across all 11 fits the worst R-hat is 1.09, in the frozen (1wk back) fit. The lowest bulk effective sample size is 38, in the frozen (1wk back) fit, and the lowest tail effective sample size is 21, in the joint fit. Only the joint fit is held to the thresholds above.</p><table tabindex="0"><thead><tr><th style="text-align:right;">fit</th><th style="text-align:right;">max_rhat</th><th style="text-align:right;">min_ess_bulk</th><th style="text-align:right;">min_ess_tail</th><th style="text-align:right;">divergences</th></tr></thead><tbody><tr><td style="text-align:right;">joint</td><td style="text-align:right;">1.073</td><td style="text-align:right;">53</td><td style="text-align:right;">21</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:right;">joint, no patches</td><td style="text-align:right;">1.034</td><td style="text-align:right;">98</td><td style="text-align:right;">132</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">exports</td><td style="text-align:right;">1.011</td><td style="text-align:right;">373</td><td style="text-align:right;">151</td><td style="text-align:right;">1</td></tr><tr><td style="text-align:right;">deaths (DRC)</td><td style="text-align:right;">1.017</td><td style="text-align:right;">311</td><td style="text-align:right;">260</td><td style="text-align:right;">28</td></tr><tr><td style="text-align:right;">cases (DRC)</td><td style="text-align:right;">1.012</td><td style="text-align:right;">308</td><td style="text-align:right;">222</td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">confirmed (DRC)</td><td style="text-align:right;">1.011</td><td style="text-align:right;">300</td><td style="text-align:right;">153</td><td style="text-align:right;">3</td></tr><tr><td style="text-align:right;">confirmed deaths (DRC)</td><td style="text-align:right;">1.013</td><td style="text-align:right;">543</td><td style="text-align:right;">386</td><td style="text-align:right;">0</td></tr><tr><td style="text-align:right;">isolation (DRC)</td><td style="text-align:right;">1.015</td><td style="text-align:right;">461</td><td style="text-align:right;">355</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:right;">onsets (DRC)</td><td style="text-align:right;">1.034</td><td style="text-align:right;">133</td><td style="text-align:right;">146</td><td style="text-align:right;">0</td></tr><tr><td style="text-align:right;">frozen (1wk back)</td><td style="text-align:right;">1.093</td><td style="text-align:right;">38</td><td style="text-align:right;">54</td><td style="text-align:right;">49</td></tr><tr><td style="text-align:right;">health zones (local)</td><td style="text-align:right;">1.018</td><td style="text-align:right;">198</td><td style="text-align:right;">374</td><td style="text-align:right;">0</td></tr></tbody></table></details><h2 id="Reproduction-number-trajectory" tabindex="-1">Reproduction number trajectory <a class="header-anchor" href="#Reproduction-number-trajectory" aria-label="Permalink to &quot;Reproduction number trajectory {#Reproduction-number-trajectory}&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>The daily reproduction number nationally and by province, with 30%, 60% and 90% credible ribbons and the national trajectory in grey behind each province.</p><p><img src="'+g+'" alt=""></p><h2 id="Infections-over-time" tabindex="-1">Infections over time <a class="header-anchor" href="#Infections-over-time" aria-label="Permalink to &quot;Infections over time {#Infections-over-time}&quot;">​</a></h2><p><img src="'+h+'" alt=""></p><p>Modelled cumulative infections, symptom onsets and deaths, with 30%, 60% and 90% credible ribbons.</p>',35)])])}const v=e(o,[["render",y]]);export{f as __pageData,v as default};
